ABSTRACT_OLD = 'Tagging all but one memory class removes the spacing penalty for recovering class weights.'
ABSTRACT_NEW = ('Tagging all but one memory class removes the spacing penalty for recovering class weights. '
                'When traders can relabel their activity, the best class restriction is partial, and class tags lose '
                'their value as relabeling becomes cheap, while an audit trail that links accounts to owners keeps it.')

LEAN_ROW = r'''Proposition~\ref{n:relabel} & best response (\texttt{hide\_best\_response}); welfare under tags (\texttt{tag\_welfare\_identity}); label-gap value (\texttt{label\_gap\_value}, \texttt{label\_gap\_attained}); tags below the audit trail (\texttt{tags\_below\_audit\_mnonneg}, \texttt{tags\_below\_audit\_mneg}); monotonicity (\texttt{tag\_value\_mono}, \texttt{outer\_branch\_mono}); hiding share below one (\texttt{hiding\_share\_lt\_one}); many classes (\texttt{routing\_near\_best}, \texttt{routing\_expensive}) & assembly of the cases (checked by brute force)\\'''
